import React from "react";
import { WeightInfoProps } from "../molecules/weightInfo";
import WeightInfo from "../molecules/weightInfo";
import { Card } from "@mui/material";



const useStyles = makeStyles<{preference : number}>()((_, {preference}) => ({
  card: {
    border: `1px solid ${theme.colors.border}`,
    padding: theme.spacing.lg,
    margin: theme.spacing.md,
    borderRadius: theme.borderRadius.lg,
    backgroundColor: 
      preference == 0 ? theme.colors.background : theme.colors.text,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center", 
    textAlign: "center",
  },
}));


const WeightCard = ({length, width, grammage, numberOfSheets, setNumberOfSheets} : WeightInfoProps) => {


    return(

        <>

            <Card>

                <WeightInfo length={length} width={width} grammage={grammage} numberOfSheets={numberOfSheets} setNumberOfSheets={setNumberOfSheets}/>

            </Card>

        </>


    )

}


export default WeightCard;
